class BlobatarParityTest {
    @Test
    fun cadaNombreDaElMismoSvgQueLaLibreriaOriginal() {
        for ((name, svg) in GOLDEN) assertEquals(svg, Blobatar.figure(name).svg(96), "seed «$name»")
    }

    @Test
    fun cubreLasDiezSiluetas() {
        val shapes = GOLDEN.take(10).map { Blobatar.figure(it.first).shape }.toSet()
        assertEquals(setOf("round", "organic", "boxy", "capsule", "nub", "cloud", "droplet", "hexagon", "sun", "triangle"), shapes)
    }

    @Test
    fun elNombreSeNormalizaComoEnLaWeb() {
        assertEquals(Blobatar.figure("alain@x.com").svg(), Blobatar.figure("  Alain@X.com ").svg())
        assertEquals(Blobatar.figure("\u00e9mile").svg(), Blobatar.figure("e\u0301mile").svg())
    }
}
